def observation(bar,selector,cutoff):
 if selector['date']>cutoff:return {'reference_id':selector['id'],'selector':selector,'known_on_saved_completed_record':selector['date'],'source_price':None,'reason':'REFERENCE_NOT_YET_KNOWN','relations':None}
 v=bars[ix[selector['date']]][selector['field']];z=D(v);rr={}
